import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Patch implements Opcodes {
 static void verify(byte[] b)throws Exception{ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods)if((m.access&(ACC_ABSTRACT|ACC_NATIVE))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);}
 public static void main(String[] args)throws Exception{Map<String,byte[]> data=new TreeMap<>();int changed=0;try(ZipFile in=new ZipFile(args[0])){for(var es=in.entries();es.hasMoreElements();){ZipEntry e=es.nextElement();byte[] b=in.getInputStream(e).readAllBytes();if(e.getName().equals("mod/cdv/gdb/ClientEvents.class")){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods){if(m.name.equals("shootEvent")){InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,0));h.add(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/gundb/Bridge","shot","(Ljava/lang/Object;)V",false));m.instructions.insert(h);for(AbstractInsnNode n:m.instructions.toArray())if(n instanceof FieldInsnNode f&&f.getOpcode()==PUTSTATIC&&f.name.equals("jamBlocked")){InsnList keep=new InsnList();keep.add(new InsnNode(POP));keep.add(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/gundb/Bridge","blockedFlag","()Z",false));m.instructions.insertBefore(n,keep);}changed++;}if(m.name.equals("animateTick")){m.instructions.insert(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/gundb/Bridge","tick","()V",false));changed++;}}ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);b=w.toByteArray();verify(b);}data.put(e.getName(),b);}}try(var fs=Files.walk(Path.of(args[2]))){for(Path p:fs.filter(x->x.toString().endsWith(".class")).toList()){byte[] b=Files.readAllBytes(p);verify(b);data.put(Path.of(args[2]).relativize(p).toString(),b);}}try(ZipOutputStream out=new ZipOutputStream(Files.newOutputStream(Path.of(args[1])))){for(var e:data.entrySet()){out.putNextEntry(new ZipEntry(e.getKey()));out.write(e.getValue());out.closeEntry();}}if(changed!=2)throw new IllegalStateException("Missing native hooks");System.out.println("Verified unjam hooks and helper bytecode");}
}
